            links = [(label, href) for label, href in _links([(url, text)]) if href not in shown]
            shown.update(href for _, href in links)
            blocks.append(url + ': ' + summary + ('\nSOURCE LINKS:\n' + '\n'.join(label + ' -> ' + _short(href, url) for label, href in links) if links else ''))
        return '\n'.join(blocks)


def _short(href, base):
    """Same-origin address as an absolute path; open_url/extract_urls resolve it against this site."""
    target, origin = urlsplit(href), urlsplit(base)
    if (target.scheme, target.netloc) != (origin.scheme, origin.netloc) or not target.path.startswith('/'):
        return href
    return urlunsplit(('', '', target.path, target.query, target.fragment))

